module adder_32bit(A,B,S,C32);
     input [32:1] A;
     input [32:1] B;
     output [32:1] S;
     output C32;

     reg [32:1] sum;
     reg C;
     integer i;

     always @ (A or B) begin
         sum = A + B;
         C = 0;
         for (i = 1; i <= 32; i = i + 1) begin
             if (sum[i] == 2'b10) begin
                 sum[i] = 1'b0;
                 sum[i-1] = sum[i-1] + 1'b1;
             end
         end
     end

     assign S = sum;
     assign C32 = C;

endmodule

