module adder_pipe_64bit
#(
    parameter DATA_WIDTH = 64,
    parameter STG_WIDTH = 16
)
(
    input clk,
    input rst_n,
    input i_en,
    input [DATA_WIDTH-1:0] adda,
    input [DATA_WIDTH-1:0] addb,
    output [DATA_WIDTH:0] result,
    output reg o_en
);

reg [DATA_WIDTH-1:0] sum1, sum2, sum3, sum4;

always @ (posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        sum1 <= 0;
        sum2 <= 0;
        sum3 <= 0;
        sum4 <= 0;
        o_en <= 0;
    end else begin
        if (i_en) begin
            sum1 <= adda + addb;
            sum2 <= sum1;
            sum3 <= sum2;
            sum4 <= sum3;
            o_en <= 1;
        end
    end
end

assign result = {sum4, o_en};

endmodule

