    if (~rst_n) begin
        o_en <= 0;
        sum1 <= 0;
        sum2 <= 0;
        sum3 <= 0;
        sum4 <= 0;
    end else begin
        if (i_en) begin
            sum1 <= adda + addb;
            sum2 <= sum1 + addb;
            sum3 <= sum2 + addb;
