            o_en <= 1;
        end else begin
            o_en <= 0;
        end
    end
end

assign result = {sum4, sum3, sum2, sum1};

endmodule

module adder_pipe_64bit
#(
    parameter DATA_WIDTH = 64,
    parameter STG_WIDTH = 16
)
(
    input clk,
    input rst_n,
    input i_en,
    input [DATA_WIDTH-1:0] adda,
    input [DATA_WIDTH-1:0] addb,
    output reg [DATA_WIDTH:0] result,
    output reg o_en
);

reg [DATA_WIDTH-1:0] sum [0:3]; // Pipeline stages

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        result <= 64'b0;
        o_en <= 1'b0;
        sum[0] <= {DATA_WIDTH{1'b0}};
        sum[1] <= {DATA_WIDTH{1'b0}};
        sum[2] <= {DATA_WIDTH{1'b0}};
        sum[3] <= {DATA_WIDTH{1'b0}};
    end
    else begin
        if (i_en) begin
            sum[0] <= adda + addb;
            sum[1] <= sum[0];
            sum[2] <= sum[1];
            sum[3] <= sum[2];
        end

        if (o_en) begin
            result <= {1'b0, sum[3]};
        end
    end
end

endmodule

module adder_pipe_64bit
#(
    parameter DATA_WIDTH = 64,
    parameter STG_WIDTH = 16
)
(
    input clk,
    input rst_n,
    input i_en,
    input [DATA_WIDTH-1:0] adda,
    input [DATA_WIDTH-1:0] addb,
    output [DATA_WIDTH:0] result,
    output reg o_en
);

reg [DATA_WIDTH-1:0] sum [3:0];

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        sum[0] <= 64'b0;
        sum[1] <= 64'b0;
        sum[2] <= 64'b0;
        sum[3] <= 64'b0;
        o_en <= 1'b0;
    end else begin
        sum[0] <= i_en ? adda + addb : sum[0];
        sum[1] <= sum[0];
        sum[2] <= sum[1];
        sum[3] <= sum[2];
        o_en <= 1'b1;
    end
end

assign result = {sum[3], sum[2], sum[1], sum[0]};

endmodule

module adder_pipe_64bit
#(
    parameter DATA_WIDTH = 64,
    parameter STG_WIDTH = 16
)
(
    input clk,
    input rst_n,
    input i_en,
    input [DATA_WIDTH-1:0] adda,
    input [DATA_WIDTH-1:0] addb,
    output [DATA_WIDTH:0] result,
    output reg o_en
);

reg [DATA_WIDTH-1:0] sum [STG_WIDTH-1:0];
integer i;

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        for (i = 0; i < STG_WIDTH; i = i + 1) begin
            sum[i] <= 0;
        end
        o_en <= 0;
    end else begin
        if (i_en) begin
            sum[0] <= adda + addb;
            for (i = 1; i < STG_WIDTH; i = i + 1) begin
                sum[i] <= sum[i-1];
            end
            o_en <= 1;
        end
    end
end

assign result = {sum[STG_WIDTH-1], sum[STG_WIDTH-1]};

endmodule

