module adder_pipe_64bit
#(
    parameter DATA_WIDTH = 64,
    parameter STG_WIDTH = 16
)
(
    input clk,
    input rst_n,
    input i_en,
    input [DATA_WIDTH-1:0] adda,
    input [DATA_WIDTH-1:0] addb,
    output reg [DATA_WIDTH:0] result,
    output reg o_en
);

reg [DATA_WIDTH-1:0] sum [0:STG_WIDTH-1];

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        o_en <= 0;
        result <= 0;
        for (int i=0; i<STG_WIDTH; i=i+1) begin
            sum[i] <= 0;
        end
    end else begin
        if (i_en) begin
            o_en <= 1;
            sum[0] <= adda + addb;
            for (int i=1; i<STG_WIDTH; i=i+1) begin
                sum[i] <= sum[i-1];
            end
            result <= sum[STG_WIDTH-1];
        end else begin
            o_en <= 0;
        end
    end
end

endmodule

