);

reg [DATA_WIDTH-1:0] sum_reg [3:0];

always @ (posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        sum_reg[0] <= 64'b0;
        sum_reg[1] <= 64'b0;
        sum_reg[2] <= 64'b0;
        sum_reg[3] <= 64'b0;
        o_en <= 1'b0;
    end else begin
        if (i_en) begin
            sum_reg[0] <= adda + addb;
            sum_reg[1] <= sum_reg[0];
            sum_reg[2] <= sum_reg[1];
            sum_reg[3] <= sum_reg[2];
            o_en <= 1'b1;
