module adder_pipe_64bit
#(
    parameter DATA_WIDTH = 64,
    parameter STG_WIDTH = 16
)
(
    input clk,
    input rst_n,
    input i_en,
    input [DATA_WIDTH-1:0] adda,
    input [DATA_WIDTH-1:0] addb,
    output [DATA_WIDTH:0] result,
    output reg o_en
);

reg [DATA_WIDTH:0] sum_reg;
reg [STG_WIDTH-1:0] stage;

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        sum_reg <= 64'b0;
        stage <= 0;
        o_en <= 0;
    end else begin
        if (i_en && stage < 4) begin
            sum_reg <= sum_reg + {adda, addb};
            stage <= stage + 1;
            o_en <= 0;
        end else if (stage == 4) begin
            result <= sum_reg;
            o_en <= 1;
        end
    end
end

endmodule

module adder_pipe_64bit
#(
    parameter DATA_WIDTH = 64,
    parameter STG_WIDTH = 16
)
(
    input clk,
    input rst_n,
    input i_en,
    input [DATA_WIDTH-1:0] adda,
    input [DATA_WIDTH-1:0] addb,
    output [DATA_WIDTH:0] result,
    output reg o_en
);

reg [DATA_WIDTH-1:0] sum;
reg [STG_WIDTH-1:0] stage;

always @ (posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        sum <= 0;
        stage <= 0;
        o_en <= 0;
    end else begin
        if (i_en) begin
            if (stage < DATA_WIDTH/STG_WIDTH) begin
                sum <= sum + adda[STG_WIDTH*stage +: STG_WIDTH] + addb[STG_WIDTH*stage +: STG_WIDTH];
                stage <= stage + 1;
            end else begin
                result <= {sum, 1'b0};
                o_en <= 1;
            end
        end
    end
end

endmodule

module asyn_fifo#(
	parameter	WIDTH = 8,
	parameter 	DEPTH = 16
)(
	input 					wclk	, 
	input 					rclk	,   
	input 					wrstn	,
	input					rrstn	,
	input 					winc	,
	input 			 		rinc	,
	input 		[WIDTH-1:0]	wdata	,

	output wire				wfull	,
	output wire				rempty	,
	output wire [WIDTH-1:0]	rdata
);

