module multi_booth_8bit (p, rdy, clk, reset, a, b);
   input clk, reset;
   input [7:0] a, b;
   output [15:0] p;
   output rdy;

   reg [15:0] p_reg;
   reg [4:0] count;
   reg [7:0] a_reg, b_reg;
   reg [7:0] b_neg;
   reg [8:0] partial_sum;

   always @(posedge clk or posedge reset) begin
      if (reset) begin
         p_reg <= 16'b0;
         count <= 5'b0;
         a_reg <= 8'b0;
         b_reg <= 8'b0;
         b_neg <= 8'b0;
         partial_sum <= 9'b0;
      end else begin
         if (count < 5) begin
            a_reg <= a;
            b_reg <= b;
            b_neg <= ~b + 1;
            count <= count + 1;
            partial_sum <= {8'b0, a_reg} + {8'b0, (count == 0) ? b_reg : b_neg};
         end else begin
            p_reg <= {partial_sum[15], partial_sum};
            count <= 5'b0;
            a_reg <= 8'b0;
            b_reg <= 8'b0;
            b_neg <= 8'b0;
            partial_sum <= 9'b0;
         end
      end
   end

   assign p = p_reg;
   assign rdy = (count == 0);
endmodule

