   reg [7:0] multiplicand;

   always @(posedge clk or posedge reset) begin
      if (reset) begin
         product <= 16'b0;
         count <= 4'b0;
         multiplier <= 8'b0;
         multiplicand <= 8'b0;
         rdy <= 1'b0;
      end else begin
         case (count)
            4'b0000: begin
               product <= {8'b0, a};
               multiplier <= a;
               multiplicand <= b;
               count <= 4'b0001;
            end
            4'b0001: begin
               if (product[0] == 1) begin
                  product <= product + {8'b0, multiplicand};
               end
               product <= product >> 1;
               count <= 4'b0010;
            end
            4'b0010: begin
               product <= product >> 1;
               count <= 4'b0011;
            end
            4'b0011: begin
               product <= {product[15], product[15:8]};
               count <= 4'b0100;
            end
            default: begin
               rdy <= 1'b1;
            end
         endcase
      end
   end

   assign p = product;

