               prod_reg <= prod_reg + (a_reg << (count*2));
            end
            count <= count + 1;
            b_reg <= {b_reg[6:0], b_reg[7]};
         end
      end
   end

   always @* begin
      rdy = (count == 4) ? 1 : 0;
