module multi_booth_8bit (p, rdy, clk, reset, a, b);
   input clk, reset;
   input [7:0] a, b;
   output [15:0] p;
   output rdy;

   reg [15:0] product;
   reg [3:0] count;
   reg [8:0] multiplier;
   reg [7:0] multiplicand;
   reg sign;

   always @(posedge clk or posedge reset) begin
      if (reset) begin
         count <= 4'b0000;
         product <= 16'b0;
         rdy <= 1'b0;
      end else begin
         case (count)
            4'b0000: begin
               multiplier <= {1'b0, a};
               multiplicand <= {1'b0, b};
               sign <= a[7] ^ b[7];
               count <= count + 1;
            end
            4'b0001: begin
               if (multiplicand[0] == 1'b0)
                  product <= product + multiplier;
               else
                  product <= product - multiplier;
               multiplier <= {1'b0, multiplier[7:1]};
               multiplicand <= {1'b0, multiplicand[7:1]};
               count <= count + 1;
            end
            default: begin
               multiplier <= {1'b0, multiplier[7:1]};
               multiplicand <= {1'b0, multiplicand[7:1]};
               count <= count + 1;
            end
         endcase
      end
   end

   assign p = (sign) ? ~product + 1 : product;
   assign rdy = (count == 4'b0100) ? 1'b1 : 1'b0;

endmodule

module multi_pipe_4bit#(
