    input rst_n,
    input [3:0] d,
    output valid_out,
    output dout
);

reg [3:0] shift_reg;
reg [2:0] counter;

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        shift_reg <= 4'b0;
        counter <= 3'b0;
        valid_out <= 1'b0;
        dout <= 1'b0;
    end else begin
        if (counter < 3) begin
            shift_reg <= {d, shift_reg[3:1]};
            counter <= counter + 1;
            valid_out <= 1'b0;
            dout <= 1'b0;
        end else begin
            valid_out <= 1'b1;
            dout <= shift_reg[0];
        end
    end
end

endmodule

module parallel2serial(
    input clk,
    input rst_n,
    input [3:0] d,
    output valid_out,
    output dout
);

reg [3:0] shift_reg;
reg valid_out_reg;
reg [3:0] counter;

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        shift_reg <= 4'b0000;
        valid_out_reg <= 1'b0;
        counter <= 4'b0000;
    end else begin
        if (counter < 4) begin
            shift_reg <= {d, shift_reg[3:1]};
            counter <= counter + 1;
        end
        if (counter == 4) begin
            dout <= shift_reg[0];
            valid_out_reg <= 1'b1;
        end
    end
end

assign valid_out = valid_out_reg;

endmodule

module parallel2serial(
    input clk,
