    if (~rst_n) begin
        shift_reg <= 4'b0;
        counter <= 3'b0;
        valid_out <= 1'b0;
    end else begin
        if (counter < 3) begin
            shift_reg <= {shift_reg[2:0], d[counter]};
            counter <= counter + 1;
        end else begin
            counter <= 3'b0;
            valid_out <= 1'b1;
        end
    end
end

assign dout = shift_reg[3];

endmodule

