);

reg [3:0] data_reg;
reg [2:0] count = 3'b111;

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        data_reg <= 4'b0000;
        count <= 3'b111;
        valid_out <= 1'b0;
