module pe(
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,

    output [31:0] c
);

reg [31:0] sum;
reg [31:0] count;

always @(posedge clk or posedge rst) begin
    if (rst) begin
        sum <= 0;
        count <= 0;
    end else begin
        if (count < 32) begin
            sum <= sum + (a << count);
            count <= count + 1;
        end
    end
end

assign c = sum + b;

