module pulse_detect(    
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);

reg prev_data;

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        data_out <= 0;
        prev_data <= 0;
    end else begin
        if (data_in & ~prev_data) begin
            data_out <= 1;
        end else begin
            data_out <= 0;
        end
        prev_data <= data_in;
    end
end

endmodule

