module serial2parallel(
	input clk,
	input rst_n,
	input din_serial,
	input din_valid,
	output reg [7:0]dout_parallel,
	output reg dout_valid
);

reg [2:0] state;
reg [7:0] shift_reg;

always @(posedge clk or negedge rst_n) begin
	if (~rst_n) begin
		state <= 3'b000;
		shift_reg <= 8'b0;
		dout_valid <= 1'b0;
	end
	else begin
		case (state)
			3'b000: begin
				if (din_valid) begin
					shift_reg <= {shift_reg[6:0], din_serial};
					state <= 3'b001;
				end
			end
			3'b001: begin
				if (din_valid) begin
					shift_reg <= {shift_reg[6:0], din_serial};
				end
				state <= 3'b010;
			end
			3'b010: begin
				if (din_valid) begin
					shift_reg <= {shift_reg[6:0], din_serial};
				end
				state <= 3'b011;
			end
			3'b011: begin
				if (din_valid) begin
					shift_reg <= {shift_reg[6:0], din_serial};
				end
				state <= 3'b000;
				dout_parallel <= shift_reg;
				dout_valid <= 1'b1;
			end
		endcase
	end
end

endmodule

