module serial2parallel(
	input clk,
	input rst_n,
	input din_serial,
	input din_valid,
	output reg [7:0] dout_parallel,
	output reg dout_valid
);

reg [2:0] state;
reg [7:0] shift_reg;

always @(posedge clk) begin
	if (~rst_n) begin
		state <= 3'b000;
		shift_reg <= 8'b0;
		dout_valid <= 1'b0;
	end
	else begin
		case(state)
			3'b000: begin // Idle state
				if (din_valid) begin
					state <= 3'b001;
					shift_reg <= {shift_reg[6:0], din_serial};
				end
			end
			3'b001: begin // Shift in data
				if (din_valid) begin
					shift_reg <= {shift_reg[6:0], din_serial};
				end
				else begin
					state <= 3'b010;
				end
			end
			3'b010: begin // Output data
				dout_parallel <= shift_reg;
				dout_valid <= 1'b1;
				state <= 3'b000;
			end
		endcase
	end
end

endmodule

module serial2parallel(
	input clk,
	input rst_n,
	input din_serial,
	input din_valid,
	output reg [7:0] dout_parallel,
	output reg dout_valid
);

reg [7:0] buffer [0:7];
reg [2:0] index = 0;

always @(posedge clk or negedge rst_n) begin
	if (~rst_n) begin
		for (int i = 0; i < 8; i = i + 1) begin
			buffer[i] <= 8'b0;
		end
		index <= 3'b0;
		dout_valid <= 0;
	end else begin
		if (din_valid) begin
			buffer[index] <= din_serial;
			index <= index + 1;
			if (index == 7) begin
				dout_parallel <= buffer[0];
				dout_valid <= 1;
			end
		end
	end
end

endmodule

