module div_16bit(
    input wire [15:0] A,
    input wire [7:0] B,
    output wire [15:0] result,
    output wire [15:0] odd
    );

reg [15:0] quotient;
reg [15:0] remainder;

always @(*) begin
    quotient <= 16'd0;
    remainder <= A;

    for (int i = 0; i < 16; i=i+1) begin
        if (remainder >= {B, 8'h0}) begin
            quotient[i] <= 1'b1;
            remainder <= remainder - {B, 8'h0};
        end else begin
            quotient[i] <= 1'b0;
        end
    end
end

assign result = quotient;
assign odd = remainder;

endmodule

module div_16bit(
