    input wire [7:0] B,
    output wire [15:0] result,
    output wire [15:0] odd
    );

    reg [15:0] quotient;
    reg [15:0] remainder;
    reg [15:0] temp;
    reg [3:0] count;

    always @(*) begin
        quotient = 16'h0;
        remainder = A;
        count = 4'b0;

        while(count < 16'h10) begin
            temp = {remainder[15], remainder} - (B << 8);
            if(temp[15] == 1 || temp[15:8] >= 8'hA) begin
                quotient[count] = 1;
                remainder = temp;
            end
            remainder = remainder << 1;
            count = count + 1;
        end

        result = quotient;
        odd = remainder;
    end

endmodule

