module traffic_light
    (
		input rst_n, 
        input clk, 
        input pass_request,
		output reg [7:0] clock,
        output reg red,
		output reg yellow,
		output reg green
    );

	parameter idle = 2'd0,
			  s1_red = 2'd1,
			  s2_yellow = 2'd2,
			  s3_green = 2'd3;

	reg [1:0] state, next_state;

	always @(posedge clk or negedge rst_n) begin
		if (~rst_n) begin
			state <= idle;
		end else begin
			state <= next_state;
		end
	end

	always @* begin
		next_state = state;
		case (state)
			idle: begin
				if (pass_request) begin
					next_state = s1_red;
				end
			end
			s1_red: next_state = s2_yellow;
			s2_yellow: next_state = s3_green;
			s3_green: next_state = idle;
		endcase
	end

	always @* begin
		red = 0;
		yellow = 0;
		green = 0;
		case (state)
			idle: begin
				red = 1;
			end
			s1_red: begin
				red = 1;
			end
			s2_yellow: begin
				yellow = 1;
			end
			s3_green: begin
				green = 1;
			end
		endcase
	end

	always @(posedge clk) begin
		if (rst_n) begin
			clock <= clock + 1;
		end
	end

endmodule

