			case(state)
				idle: begin
					if (pass_request) begin
						state <= s1_red;
						count <= 8'b0;
					end
				end
				s1_red: begin
					if (count == 8'd5) begin
						state <= s2_yellow;
						count <= 8'b0;
					end
					else begin
						count <= count + 1;
					end
