				s2_yellow: begin
					if (count == 8'd3) begin
						state <= s3_green;
						count <= 8'b0;
					end
					else begin
						count <= count + 1;
					end
				end
				s3_green: begin
					if (count == 8'd8) begin
						state <= idle;
						count <= 8'b0;
					end
					else begin
						count <= count + 1;
					end
				end
			endcase
		end
	end

	always @* begin
		red = (state == s1_red) ? 1'b1 : 1'b0;
		yellow = (state == s2_yellow) ? 1'b1 : 1'b0;
		green = (state == s3_green) ? 1'b1 : 1'b0;
