					yellow <= 1'b1;
					green <= 1'b0;
					clock <= 8'b00000100;
				end
				s3_green: begin
					red <= 1'b0;
					yellow <= 1'b0;
					green <= 1'b1;
					clock <= 8'b00001000;
				end
			endcase
		end
	end

endmodule

module traffic_light
    (
		input rst_n, 
        input clk, 
        input pass_request,
		output reg [7:0] clock,
        output reg red,
		output reg yellow,
		output reg green
    );

	parameter 	idle = 2'd0,
				s1_red = 2'd1,
				s2_yellow = 2'd2,
				s3_green = 2'd3;

	reg [1:0] state;
	reg [7:0] count;

	always @(posedge clk or negedge rst_n) begin
		if (~rst_n) begin
			state <= idle;
			red <= 1'b0;
			yellow <= 1'b0;
			green <= 1'b0;
			count <= 8'b0;
		end else begin
			case(state)
				idle: begin
					if (pass_request) begin
						state <= s1_red;
						count <= 8'b0;
					end
				end
				s1_red: begin
					red <= 1'b1;
					if (count == 8'd10) begin
						state <= s2_yellow;
						count <= 8'b0;
						red <= 1'b0;
					end else begin
						count <= count + 1;
					end
				end
				s2_yellow: begin
					yellow <= 1'b1;
					if (count == 8'd5) begin
						state <= s3_green;
						count <= 8'b0;
						yellow <= 1'b0;
					end else begin
						count <= count + 1;
					end
				end
				s3_green: begin
					green <= 1'b1;
					if (count == 8'd15) begin
						state <= idle;
						count <= 8'b0;
						green <= 1'b0;
					end else begin
						count <= count + 1;
					end
				end
			endcase
		end
	end

endmodule

module traffic_light
    (
		input rst_n, 
        input clk, 
        input pass_request,
		output wire[7:0] clock,
        output reg red,
		output reg yellow,
		output reg green
    );

	parameter 	idle = 2'd0,
				s1_red = 2'd1,
				s2_yellow = 2'd2,
				s3_green = 2'd3;

	reg [1:0] state, next_state;

	always @(posedge clk or negedge rst_n) begin
		if (~rst_n) begin
			state <= idle;
		end
		else begin
			state <= next_state;
		end
	end

	always @(*) begin
		case(state)
			idle: begin
				red <= 1'b0;
				yellow <= 1'b0;
				green <= 1'b0;
				if (pass_request) begin
					next_state = s1_red;
				end
				else begin
					next_state = idle;
				end
			end

			s1_red: begin
				red <= 1'b1;
				yellow <= 1'b0;
				green <= 1'b0;
				next_state = s2_yellow;
			end

			s2_yellow: begin
				red <= 1'b0;
				yellow <= 1'b1;
				green <= 1'b0;
				next_state = s3_green;
			end

			s3_green: begin
				red <= 1'b0;
				yellow <= 1'b0;
				green <= 1'b1;
				next_state = idle;
			end
		endcase
	end

	always @(posedge clk) begin
		clock <= clock + 1;
	end

endmodule

module traffic_light
    (
		input rst_n, 
        input clk, 
        input pass_request,
		output reg [7:0] clock,
        output reg red,
		output reg yellow,
		output reg green
    );

	parameter idle = 2'd0,
			  s1_red = 2'd1,
			  s2_yellow = 2'd2,
			  s3_green = 2'd3;

	reg [1:0] state;

	always @(posedge clk or negedge rst_n) begin
		if (~rst_n) begin
			state <= idle;
			red <= 1'b0;
			yellow <= 1'b0;
			green <= 1'b0;
		end
		else begin
			case(state)
				idle: begin
					if (pass_request) begin
						state <= s1_red;
					end
				end
				s1_red: begin
					state <= s2_yellow;
					red <= 1'b1;
					yellow <= 1'b0;
					green <= 1'b0;
				end
				s2_yellow: begin
					state <= s3_green;
					red <= 1'b0;
					yellow <= 1'b1;
					green <= 1'b0;
				end
				s3_green: begin
					state <= idle;
					red <= 1'b0;
					yellow <= 1'b0;
					green <= 1'b1;
				end
			endcase
		end
	end

	always @(posedge clk or negedge rst_n) begin
		if (~rst_n) begin
			clock <= 8'b0;
		end
		else begin
			if (clock == 8'b11111111) begin
				clock <= 8'b0;
			end
			else begin
				clock <= clock + 1;
			end
		end
	end

endmodule

