module width_8to16(
	input 				clk 	,   
	input 				rst_n	,
	input				valid_in,
	input	[7:0]		data_in,
	output	reg			valid_out,
	output  reg [15:0]	data_out
);

always @(posedge clk or negedge rst_n) begin
	if (~rst_n) begin
		valid_out <= 1'b0;
		data_out <= 16'b0;
	end
	else begin
		if (valid_in) begin
			valid_out <= 1'b1;
			data_out[7:0] <= data_in;
			data_out[15:8] <= 8'b0;
		end
		else begin
			valid_out <= 1'b0;
			data_out <= 16'b0;
		end
	end
end

endmodule

